import urllib.request,zipfile,io
u='https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1005659.s001&type=supplementary'
try:
 b=urllib.request.urlopen(u,timeout=40).read()
 z=zipfile.ZipFile(io.BytesIO(b))
 print('\\n'.join(z.namelist()))
 for n in z.namelist():
  if n.endswith(('.py','.txt','.md')):
   print('FILE:',n); print(z.read(n).decode(errors='replace')[:40000])
except Exception as e: print(type(e).__name__,str(e))
PY"

