/bin/bash -lc "python3 - <<'PY'
import urllib.request,zipfile,io,hashlib
u='https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1005659.s001&type=supplementary'
b=urllib.request.urlopen(u,timeout=40).read(); z=zipfile.ZipFile(io.BytesIO(b))
print('archive_bytes',len(b),'sha256',hashlib.sha256(b).hexdigest())
for n in ['SI/Benchmarks/README.txt','SI/Benchmarks/energyBenchmarks.py','SI/Benchmarks/dhfr.pdb']:
 d=z.read(n); print(n,'bytes',len(d),'sha256',hashlib.sha256(d).hexdigest())
 if not n.endswith('.pdb'): print(d.decode())
 else: print('atoms',sum(l.startswith((b'ATOM  ',b'HETATM')) for l in d.splitlines()))
PY"

